【构造函数】&quot;); foreach (var ctor in type.GetConstructors()) &#123; var parameters = ctor.GetParameters(); string paramList = string.Join(&quot;, &quot;, parameters.Select(p =&gt; $&quot;&#123;p.ParameterType.Name&#125; &#123;p.Name&#125;&quot;)); Console.WriteLine($&quot; &#123;type.Name&#125;(&#123;paramList&#125;)&quot;); &#125; // 方法（只显示自定义方法，过滤掉继承的） Console.WriteLine($&quot;
【方法（仅本类型声明）】&quot;); var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly); foreach (var m in methods) &#123; if (m.IsSpecialName) continue; // 跳过属性/事件的访问器 var parameters = m.GetParameters(); string paramList = string.Join(&quot;, &quot;, parameters.Select(p =&gt; $&quot;&#123;p.ParameterType.Name&#125; &#123;p.Name&#125;&quot;)); Console.WriteLine($&quot; &#123;m.ReturnType.Name&#125; &#123;m.Name&#125;(&#123;paramList&#125;)&quot;); &#125; // 属性 Console.WriteLine($&quot;
【属性】&quot;); foreach (var p in type.GetProperties()) &#123; Console.WriteLine($&quot; &#123;p.PropertyType.Name&#125; &#123;p.Name&#125; &#123;&#123; &#123;(p.CanRead ? &quot;get;&quot; : &quot;&quot;)&#125; &#123;(p.CanWrite ? &quot;set;&quot; : &quot;&quot;)&#125; &#125;&#125;&quot;); &#125; // 字段 Console.WriteLine($&quot;
【字段】&quot;); foreach (var f in type.GetFields(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)) &#123; string staticFlag = f.IsStatic ? &quot;static &quot; : &quot;&quot;; Console.WriteLine($&quot; &#123;staticFlag&#125;&#123;f.FieldType.Name&#125; &#123;f.Name&#125;&quot;); &#125; &#125;&#125;// 使用示例TypeBrowser.Browse(typeof(List&lt;string&gt;)); 八、常见陷阱与最佳实践 陷阱：GetMethod 可能返回 null 12345// ❌ 错误：如果存在重载，GetMethod(&quot;Add&quot;) 可能返回 nullMethodInfo method = typeof(List&lt;int&gt;).GetMethod(&quot;Add&quot;); // 实际上能工作，但不可靠// ✅ 正确：指定参数类型MethodInfo method = typeof(List&lt;int&gt;).GetMethod(&quot;Add&quot;, new Type[] &#123; typeof(int) &#125;); 陷阱：GetProperties 不会返回显式实现接口的属性 123456789interface IMyInterface &#123; string Name &#123; get; &#125; &#125;class MyClass : IMyInterface &#123; string IMyInterface.Name =&gt; &quot;explicit&quot;; // 这个得不到 public string Name =&gt; &quot;public&quot;; // 只得到这个&#125;Type t = typeof(MyClass);var props = t.GetProperties(); // 只得到 public Name，得不到显式实现的 解决方案： 通过接口 Type 获取 1var interfaceProp = typeof(IMyInterface).GetProperty(&quot;Name&quot;); 最佳实践：缓存反射结果 1234567891011121314151617public static class TypeCache&#123; private static readonly Dictionary&lt;Type, PropertyInfo[]&gt; _properties = new(); public static PropertyInfo[] GetProperties(Type type) &#123; lock (_properties) &#123; if (!_properties.TryGetValue(type, out var props)) &#123; props = type.GetProperties(); _properties[type] = props; &#125; return props; &#125; &#125;&#125; 最佳实践：使用 nameof 避免魔法字符串 12345// ❌ 不好：魔法字符串，重构时容易出错MethodInfo method = t.GetMethod(&quot;Add&quot;);// ✅ 好：nameof 编译时检查MethodInfo method = t.GetMethod(nameof(List&lt;int&gt;.Add)); 九、本篇速查表 想要获取 方法 注意事项 构造函数 GetConstructors() 用 BindingFlags.NonPublic 获取私有构造 方法 GetMethods() 包含属性/事件的 get/set 方法 属性 GetProperties() 不包含显式接口实现 字段 GetFields() 默认不含静态字段 事件 GetEvents() 可通过 AddMethod/RemoveMethod 获取委托方法 接口 GetInterfaces() 包含所有继承的接口 所有成员 GetMembers() 最全，但需要过滤 基类 BaseType object 的基类是 null 判断继承 IsSubclassOf / IsAssignableFrom 前者不含自身，后者含 判断实例 IsInstanceOfType 等价于 is 关键字 十、思考题 typeof(List&lt;&gt;).GetMethods() 和 typeof(List&lt;int&gt;).GetMethods() 返回的结果有什么不同？ 特性 typeof(List&lt;&gt;) typeof(List) 术语 泛型类型定义 (Unbound) 已构造的泛型类型 (Bound/Closed) ContainsGenericParameters true false 方法参数类型 占位符 T 明确的 Int32 能否直接 Invoke 否 (会抛出异常) 是 元数据标记 属于通用模板 属于该特定类型的运行时生成实例 12345678var openMethod = typeof(List&lt;&gt;).GetMethod(&quot;Add&quot;);var closedMethod = typeof(List&lt;int&gt;).GetMethod(&quot;Add&quot;);Console.WriteLine(openMethod.GetParameters()[0].ParameterType.IsGenericParameter); // True (它是 T)Console.WriteLine(closedMethod.GetParameters()[0].ParameterType.IsGenericParameter); // False (它是 int)Console.WriteLine(openMethod.GetParameters()[0].ParameterType); // 输出 TConsole.WriteLine(closedMethod.GetParameters()[0].ParameterType); // 输出 System.Int32 IsAssignableFrom 和 is 关键字有什么本质区别？ 操作对象不同 is 关键字：操作的是对象实例。它检查一个具体的“东西”是否兼容于某种类型。 语义： “这个苹果是一个水果吗？” IsAssignableFrom：操作的是类型对象 (Type)。它检查两个“类别”之间是否存在派生或实现关系。 语义： “水果这个分类可以用来存放苹果这个分类的对象吗？” 绑定时间不同 is：通常在编译期确定部分逻辑（尽管结果在运行时判定），语法简洁，常用于类型转换前的安全检查。 IsAssignableFrom：是反射 (Reflection) 的一部分。它完全在运行期动态解析。当你只知道两个 Type 变量，而没有具体实例时，它是唯一的选择。 核心语法对比 特性 obj is T typeA.IsAssignableFrom(typeB) 输入 左边是实例，右边是类型名 两边都是 Type 实例 Null 处理 如果 obj 为 null，始终返回 false 不涉及实例，仅对比类型定义 性能 极快（编译器优化） 较慢（涉及反射元数据查找） 适用场景 业务逻辑中的类型判断与转换 插件系统、依赖注入、泛型约束检查

字符编码基础 计算机中储存的信息都是用二进制数表示的；而我们在屏幕上看到的英文、汉字等字符是二进制数转换之后的结果。通俗的说，按照何种规则将字符存储在计算机中，如’a’用什么表示，称为&quot;编码&quot;；反之，将存储在计算机中的二进制数解析显示出来，称为&quot;解码&quot;，如同密码学中的加密和解密。在解码过程中，如果使用了错误的解码规则，则导致’a’解析成’b’或者乱码。 核心概念的铁三角关系 不要把“字符集”和“字符编码”混为一谈！我们用**“新华字典”**来做个比喻： 字符集（Character Set）：字库里有哪些字。 比喻：国家出版了一本《新华字典》，里面收录了10000个汉字。这本字典本身就是“字符集”。 举例：ASCII（只收录英文字母和符号）、GB2312（收录常用汉字）、Unicode（野心极大，收录地球上所有语言的字符，甚至包括 Emoji 表情😀）。 码位（Code Point）：字符在字典里的“页码”。 比喻：“中”字在《新华字典》的第 1500 页。这个“1500”就是码位。 举例：在 Unicode 这本大字典里，“中”字的码位被规定为 U+4E2D（4E2D 是十六进制，转换成十进制是 20013）。注意：码位只是一个数学概念，还不是计算机里的0和1。 字符编码（Character Encoding）：把页码变成计算机字节的“规则”。 比喻：我现在要把“1500”这个页码存到硬盘上，我是用 2 个字节存，还是 4 个字节存？我是顺着存，还是倒着存？ 举例：UTF-8、UTF-16、GBK 都是编码规则。同样是存“中”字（码位 U+4E2D），UTF-8 规则说：“我要用3个字节存（E4 B8 AD）”；UTF-16 规则说：“我用2个字节就够了（4E 2D）”。 C# 新手避坑： C# 中的 string 本质上是一串 char 数组。 char 在 C# 中占用 2个字节，它代表的其实是一个 UTF-16 的代码单元（我们后面会讲）。 编码的演进 ASCII：一切的起点（美国人的傲慢） 7位编码（最高位补0，凑成1个字节），总共只能表示 128 个字符。 包含：英文字母（a-z, A-Z）、数字（0-9）、标点符号和一些控制字符（回车、换行）。 现状：所有现代编码（除了UTF-16/32）都完全兼容 ASCII。 ANSI / MBCS（多字节字符集）：诸侯割据的“地方方言” 背景：计算机普及到欧洲、亚洲，128个字符根本不够用。于是各国开始自己造字典。 中国造了 GB2312（后来扩充为 GBK，再后来是 GB18030），用 2 个字节表示一个汉字。 台湾造了 Big5（繁体字）。 日本造了 Shift_JIS。 灾难：在 Windows 系统中，微软把这些本地编码统称为 ANSI，并引入了“代码页（Code Page）”的概念（中文大陆系统默认代码页是 936，代表 GBK）。如果你把一个日本程序员用 Shift_JIS 写的文本，发给中国程序员用 GBK 的电脑打开，就会出现经典的 “锟斤拷”、“烫烫烫”等乱码。 Unicode：宇宙大一统的字符集 使命：把全世界所有字符放进一本字典里，彻底终结 ANSI 时代的乱码战争。 记住：Unicode 只是规定了所有字符的“码位”（ID号），它没有规定在硬盘上怎么存（0和1怎么排），怎么存是 UTF 家族的事。 UTF-8 vs UTF-16 vs UTF-32：谁才是最优解？ 它们都是把 Unicode 码位翻译成字节的“编码规则”。 UTF-8：Web 和现代系统的绝对霸主（变长：1~4字节） 规则：英文字母占 1 个字节（和ASCII一模一样，完美兼容），常用汉字占 3 个字节，Emoji表情占 4 个字节。 优点：极度节省英文文本的空间；没有“字节序（大小端）”问题；互联网传输的绝对标准（HTTP、JSON、HTML 默认全用它）。 C# 现状：.NET Core 和 .NET 5+ 以后，整个微软生态全面拥抱 UTF-8。 UTF-16：Windows 和 C# 内存中的“内室总管”（定长/变长：2或4字节） 规则：绝大多数常用字符（包括汉字）占 2 个字节，极少数生僻字和 Emoji 占 4 个字节。 优点：处理字符串速度快（在内存中找字符比 UTF-8 容易计算）。 C# 必考知识点：C# 程序运行在内存中时，所有的 string 和 char 都是 UTF-16 编码的！ 坑：既然 C# 中一个 char 是 2 个字节，那如果你在字符串里写一个 Emoji 😀（占4个字节），C# 会认为这个 Emoji 长度是 2！ &quot;😀&quot;.Length == 2 （新手往往会因为这个在截取字符串时报错）。 命名槽点：在 C# 代码里，如果你调用 System.Text.Encoding.Unicode，它实际上指的是 UTF-16，而不是宏观意义上的 Unicode！（这是微软早期留下的历史遗留命名问题）。 UTF-32：极其浪费空间的土豪（严格定长：4字节） 规则：管你是字母 ‘A’ 还是汉字 ‘中’，统统用 4 个字节存。 缺点：文本体积直接膨胀几倍。几乎没有人会在存文件或网络传输时用它。 BOM是什么？ 这绝对是每一个初级程序员都会掉进去的大坑！ 它的初衷是好的： BOM 叫“字节序标记”。在文件的最开头，偷偷塞进几个隐藏的字节。 比如，Windows 记事本在保存 UTF-8 文件时，会在文件最开头加上 EF BB BF 三个字节。 这样一来，任何软件打开这个文件，只要看到开头有这三个字节，就知道：“哦！这是一个 UTF-8 编码的文件”，直接按 UTF-8 解析，绝不乱码。 为什么它是“万恶之源”？ Linux、Mac OS 和现代开源软件极度讨厌 BOM。它们认为 UTF-8 根本不需要什么标记。 现象 1：如果你用带 BOM 的 UTF-8 保存了一段 C# / Java / Python 代码，跑到 Linux 服务器上编译，编译器会报错：“识别不了第一行的非法字符”。 现象 2：写 Web API 返回一个带 BOM 的 JSON 给前端，前端解析直接崩溃，因为 JSON 字符串开头多了三个看不见的空字符。 C# 新手避坑指南： 在 C# 中，尽量永远使用 不带 BOM 的 UTF-8。 如果你在 C# 里实例化 UTF8：12345// 带有 BOM 的 UTF8 (不要用这个来写文件发给别的系统！)Encoding utf8WithBom = Encoding.UTF8; // 不带 BOM 的纯净 UTF8 (推荐做法！❤️)Encoding utf8NoBom = new UTF8Encoding(false); 实战演示代码 作为新手，你可以把这段代码复制到控制台程序（Console App）里跑一下，直观感受一下编码的魔力： 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647using System;using System.Text;class Program&#123; static void Main() &#123; // 注册提供程序，否则现代 .NET 可能不支持 GBK (如果是老 .NET Framework 则不需要这行) Encoding.RegisterProvider(CodePagesEncodingProvider.Instance); string text = &quot;C#汉字😀&quot;; // 包含英文(1) + 符号(1) + 汉字(2) + Emoji(1) Console.WriteLine($&quot;原始字符串: &#123;text&#125;&quot;); Console.WriteLine($&quot;C#中的长度 (string.Length): &#123;text.Length&#125;&quot;); // 结果是 6！因为 Emoji 占了 2 个 char Console.WriteLine(&quot;
--- 开始按不同规则编码成字节 (存入硬盘的形态) ---&quot;); // 1. UTF-8 规则 byte[] utf8Bytes = Encoding.UTF8.GetBytes(text); Console.WriteLine($&quot;UTF-8 字节数: &#123;utf8Bytes.Length&#125;&quot;); // 算一算: C(1) + #(1) + 汉(3) + 字(3) + 😀(4) = 12字节 PrintBytes(utf8Bytes); // 2. GBK 规则 Encoding gbk = Encoding.GetEncoding(&quot;GBK&quot;); byte[] gbkBytes = gbk.GetBytes(text); Console.WriteLine($&quot;
GBK 字节数: &#123;gbkBytes.Length&#125;&quot;); // 算一算: C(1) + #(1) + 汉(2) + 字(2) + 😀(GBK字典里没有Emoji，会变成一个?号，占1字节) = 7字节 PrintBytes(gbkBytes); // 3. 经典乱码重现：用错误的方式打开！ Console.WriteLine(&quot;
--- 灾难现场：用 UTF-8 的规则去读取 GBK 存的字节 ---&quot;); string badString = Encoding.UTF8.GetString(gbkBytes); Console.WriteLine(badString); // 打印结果：C#? (这就是经典的菱形问号乱码) &#125; // 辅助方法：把字节数组打印成十六进制 static void PrintBytes(byte[] bytes) &#123; Console.Write(&quot;十六进制内容: &quot;); foreach (byte b in bytes) &#123; Console.Write($&quot;&#123;b:X2&#125; &quot;); // X2 表示以两位的十六进制大写打印 &#125; Console.WriteLine(); &#125;&#125; 总结一下： 内存中操作字符串（如 Substring, Replace），C# 默默用的是 UTF-16。 存入数据库、写入本地文件、通过 Web API 发送给前端，一定要主动转换成 无 BOM 的 UTF-8。 遇到老旧国企系统对接、古董级设备通信，才可能需要请出 GBK (GB2312)。 保持这个世界观，你以后处理所有的文本文件和网络数据传输，都能一眼看穿乱码的本质！

如果说前面的整数（补码）是在教你如何用极度精确、一成不变的砖块搭建金字塔，那么现在的浮点数，就是在教你如何用有限的画笔，去描绘广袤无垠、且可以无限细分的真实宇宙。 在现实世界里，从原子的直径（极小）到星系的距离（极大），我们需要表示的数值跨度是恐怖的。更糟糕的是，实数是无限连续的（比如 1 和 2 之间有无数个小数）。但我们的寄存器只有可怜的 32 位或 64 位。 IEEE 754 浮点数标准，是计算机科学史上最精妙的妥协，也是一次天才的黑客行为。它成功用极其有限的比特，完美模拟了连续宇宙的错觉。但这套机制极其复杂，且充满了违背常理的数学陷阱。 浮点数 基础预热：二进制小数 在认识浮点数之前，我们先得搞懂：二进制怎么表示小数？ 在十进制里，小数点右边的权重是 10−110^{-1}10−1 (0.1), 10−210^{-2}10−2 (0.01)… 在二进制里，完全一样！小数点右边的权重是 2−12^{-1}2−1 (0.5), 2−22^{-2}2−2 (0.25), 2−32^{-3}2−3 (0.125)… 10.1 (二进制) = 21+0+2−12^1 + 0 + 2^{-1}21+0+2−1 = 2+0.52 + 0.52+0.5 = 2.5 (十进制) 0.11 (二进制) = 2−1+2−22^{-1} + 2^{-2}2−1+2−2 = 0.5+0.250.5 + 0.250.5+0.25 = 0.75 (十进制) 第一个致命缺陷出现了： 二进制小数只能极其精确地表示那些能够拆分成 12,14,18 rac{1}{2},  rac{1}{4},  rac{1}{8}21​,41​,81​ 等分数之和的数字。 像十进制的 0.1 或者是 0.2，在二进制世界里是无限循环小数！这就注定了浮点数从诞生起，就带有先天性的精度丢失。 IEEE 754 标准：计算机里的“科学计数法” 把小数全塞进固定位置是行不通的（那叫定点数）。为了应对宇宙级的跨度，IEEE 制定了类似科学计数法的终极公式： V=(−1)s×M×2EV = (-1)^s 	imes M 	imes 2^E V=(−1)s×M×2E 这三个字母代表了浮点数的灵魂： 符号位 (sss, Sign)：决定是正数 (s=0s=0s=0) 还是负数 (s=1s=1s=1)。 尾数 (MMM, Significand/Mantissa)：一个大于等于 1、小于 2 的纯小数（比如 1.234）。它决定了数字的精度。 阶码/指数 (EEE, Exponent)：2 的几次方。它决定了数字的大小范围。 内存布局（这 32 个抽屉怎么分配？） 在 C# 的 float (单精度 32位) 中，内存被死死切成了 3 段： sss (1 位)：第 31 位。 expexpexp (8 位)：第 23~30 位。用于计算阶码 EEE。 fracfracfrac (23 位)：第 0~22 位。用于计算尾数 MMM。 对于 double (双精度 64位)：sss(1位), expexpexp(11位), fracfracfrac(52位)。 根据 expexpexp 划分的四个世界 浮点数不是一套规则走到底的，根据中间那 8 位的 expexpexp（指数位）的不同，浮点数被分为了四个完全不同的“门派”。这正是 IEEE 754 最天才的地方。 规格化的值 —— 绝大部分日常数值 条件： expexpexp 既不是全 0 (00000000)，也不是全 1 (11111111)。 这里有两个极其骚气的黑客级设计： 指数的偏置 (Biasing)： expexpexp 有 8 位，当成无符号数看是 1 到 254。但是我们要表示负指数（极小的数）和正指数（极大的数）怎么办？ IEEE 规定：E=exp−BiasE = exp - BiasE=exp−Bias (偏置量)。 对于 32 位 float，Bias=127Bias = 127Bias=127。 所以，如果 expexpexp 是 128，那么真实指数 E=128−127=1E = 128 - 127 = 1E=128−127=1。 如果 expexpexp 是 100，那么真实指数 E=100−127=−27E = 100 - 127 = -27E=100−127=−27。 隐藏的 1 (Implied leading 1)： 既然是科学计数法，尾数 MMM 永远是 1.xxxxx1.xxxxx1.xxxxx。既然永远是以 1 开头，那我为什么还要浪费 1 个比特把它存进内存呢？ 天才！IEEE 规定，M=1+fM = 1 + fM=1+f（fff 就是内存里的 fracfracfrac 位）。 这就等于 “花 23 位的钱，买到了 24 位的精度！” 非规格化的值 条件： expexpexp 是全 0 (00000000)。 当我们想表示极其接近 0 的数字，甚至就是真实的 0.0 时，第一门派失效了（因为它永远自带一个隐藏的 1，永远不能表示绝对的 0）。 此时系统自动切换到“显微镜模式”： 真实的 0：如果 expexpexp 为 0，且 fracfracfrac 也全为 0，这才是真正的 0.0！（而且因为符号位的存在，浮点数有 +0.0 和 -0.0 两个零）。 没有隐藏的 1：M=fM = fM=f （不再加 1 了）。 平滑过渡（逐渐下溢）：此时指数固定为 E=1−Bias=−126E = 1 - Bias = -126E=1−Bias=−126。这保证了非规格化数字能够平滑地衔接到规格化数字的最小边界，不会产生突然断裂的鸿沟。 特殊值 条件： expexpexp 是全 1 (11111111)。 无穷大 (Infinity)：当 fracfracfrac 全为 0 时。表示这个数字大到寄存器爆炸了。 比如，1.0 / 0.0 在浮点运算中不会崩溃，它会得到正无穷（+Infinity）。 不是一个数 (NaN, Not a Number)：当 fracfracfrac 不全为 0 时。 比如，你试图计算 −1\sqrt{-1}−1​，或者 Infinity - Infinity，计算机会返回 NaN，意思是：“算不出来了，毁坏了，别管我”。 C# 代码实战：查看Float 文字太抽象，让我们写一段极其硬核的 C# 代码。我们将输入一个 float，扒开它 32 位的皮囊，将它底层的 sss、expexpexp 和 fracfracfrac 抽丝剥茧地展示出来！ 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647using System;public class FloatAnatomyDemo&#123; public static void Run() &#123; Console.WriteLine(&quot;=== 1. 像外科医生一样解剖 Float ===&quot;); // 尝试不同的数字，看看它们的底层表现 // float target = 15.25f; // 可以试着改这些数字: 0.15625f, 0.0f, -0.0f, float.PositiveInfinity float target = 0.15625f; // 1/8 + 1/32 // C# 高级技巧：通过 BitConverter 将浮点数的内存原封不动转为整数，方便按位操作 int bits = BitConverter.SingleToInt32Bits(target); // 使用掩码提取三大部分 int s = (bits &gt;&gt; 31) &amp; 1; // 提取最高位 int exp = (bits &gt;&gt; 23) &amp; 0xFF; // 提取中间8位 int frac = bits &amp; 0x7FFFFF; // 提取尾部23位 Console.WriteLine($&quot;观察目标数值: &#123;target&#125;&quot;); Console.WriteLine($&quot;32位二进制: &#123;Convert.ToString(bits, 2).PadLeft(32, &#x27;0&#x27;)&#125;&quot;); Console.WriteLine($&quot;符号位 (s): &#123;s&#125;&quot;); Console.WriteLine($&quot;阶码 (exp): &#123;exp&#125; (二进制: &#123;Convert.ToString(exp, 2).PadLeft(8, &#x27;0&#x27;)&#125;)&quot;); Console.WriteLine($&quot;尾数 (frac): &#123;frac&#125; (二进制: &#123;Convert.ToString(frac, 2).PadLeft(23, &#x27;0&#x27;)&#125;)&quot;); // 解释含义 (假设它是规格化数) if (exp &gt; 0 &amp;&amp; exp &lt; 255) &#123; int E = exp - 127; double M = 1.0 + (frac / Math.Pow(2, 23)); Console.WriteLine(&quot;
此为【规格化的值】：&quot;); Console.WriteLine($&quot;真实指数 E = &#123;exp&#125; - 127 = &#123;E&#125;&quot;); Console.WriteLine($&quot;真实尾数 M = 1.0 + (frac / 2^23) = &#123;M&#125;&quot;); double realValue = Math.Pow(-1, s) * M * Math.Pow(2, E); Console.WriteLine($&quot;验算公式: (-1)^&#123;s&#125; * &#123;M&#125; * 2^&#123;E&#125; = &#123;realValue&#125;&quot;); &#125; else if (exp == 255) &#123; Console.WriteLine(&quot;
此为【特殊值】(Infinity 或 NaN)&quot;); &#125; else if (exp == 0) &#123; Console.WriteLine(&quot;
此为【非规格化的值】(极小值或0)&quot;); &#125; &#125;&#125; 舍入规则：为什么计算机“向偶数舍入”？ 浮点数的尾数是有限的（23位），就像你试图在一个小盒子里装下整个太平洋，大部分水只能被溢出舍弃（Rounding）。 我们小学学的是“四舍五入”（逢 5 进 1）。 但 IEEE 754 默认使用的是：“向偶数舍入 (Round-to-even)”。 意思是：如果要舍弃的部分刚好是正中间（比如 1.5, 2.5），那就向最靠近的偶数靠拢。 1.5 →ightarrow→ 2.0 2.5 →ightarrow→ 2.0 （注意，没有变成 3.0！） 为什么要这么奇葩？ 这是因为统计学偏差！如果我们在海量数据运算中，遇到 0.5 总是无脑向上舍入（四舍五入），那么所有中间值的舍入误差全是正数。经过几千万次累加后，结果会比真实值大得多！ “向偶数舍入”非常聪明地让 50% 的几率向上舍入，50% 的几率向下舍入，从而在统计学上把误差完美地抵消了！ C# 代码演示：舍入的真相 在 C# 中，原生的 Math.Round 完美继承了 IEEE 标准，默认就是向偶数舍入（即 Bank’s Rounding 银行家舍入法）。 123456789101112131415161718using System;public class RoundingDemo&#123; public static void Run() &#123; Console.WriteLine(&quot;
=== 2. 舍入：奇葩但科学的“向偶数舍入” ===&quot;); double num1 = 1.5; double num2 = 2.5; Console.WriteLine($&quot;Math.Round(&#123;num1&#125;) = &#123;Math.Round(num1)&#125;&quot;); Console.WriteLine($&quot;Math.Round(&#123;num2&#125;) = &#123;Math.Round(num2)&#125; &lt;-- 看看！它向下变成了偶数 2！&quot;); // 如果你强迫症，非要小学教的四舍五入，你需要额外传参： Console.WriteLine($&quot;Math.Round(&#123;num2&#125;, MidpointRounding.AwayFromZero) = &#123;Math.Round(num2, MidpointRounding.AwayFromZero)&#125; (小学算法)&quot;); &#125;&#125; 浮点运算的陷阱：被粉碎的结合律 这是无数新手程序员掉入的无底深渊，也是 CSAPP 给我们的最沉重警告。 在数学中，加法结合律永远成立：(a+b)+c=a+(b+c)(a + b) + c = a + (b + c)(a+b)+c=a+(b+c)。 但在计算机的浮点数中，结合律被彻底粉碎！ 想象一下，你有一个天文级的巨大数字（比如宇宙的直径），然后你给它加上一粒沙子的大小，然后再减去这个宇宙的直径。按理说，结果应该等于一粒沙子，对吧？ 错！当你把沙子加给宇宙时，由于浮点数的尾数容量有限，为了能够把指数“对齐”，沙子的那一点点微末数据会被无情地推出尾数范围，直接丢弃（被大海吞噬了）。 C# 代码演示：浮点黑洞效应 1234567891011121314151617181920212223242526272829303132using System;public class FloatAssociativityDemo&#123; public static void Run() &#123; Console.WriteLine(&quot;
=== 3. 浮点陷阱：结合律的崩塌与精度黑洞 ===&quot;); float a = 3.14f; float huge = 1e20f; // 10 的 20 次方，极其巨大的数 float minusHuge = -1e20f; // 场景 1：先算大数加减 (huge + minusHuge 互相抵消为 0) float result1 = a + (huge + minusHuge); Console.WriteLine($&quot;场景1: 3.14 + (1e20 - 1e20) = &#123;result1&#125;&quot;); // 场景 2：按照从左到右执行 (3.14 先加上 1e20) float result2 = (a + huge) + minusHuge; Console.WriteLine($&quot;场景2: (3.14 + 1e20) - 1e20 = &#123;result2&#125;&quot;); if (result1 != result2) &#123; Console.WriteLine(&quot;
震惊！加法结合律失效！&quot;); Console.WriteLine(&quot;原因：在计算 (3.14 + 1e20) 时，3.14 相对于 1e20 太小了，&quot;); Console.WriteLine(&quot;它的有效位直接被【截断/舍弃】了！等价于 1e20 + 0。&quot;); Console.WriteLine(&quot;所以随后减去 1e20 时，结果变成了 0！&quot;); &#125; Console.WriteLine(&quot;
这也解释了为什么金融系统算钱【绝对不能用 float/double】，必须用 decimal！&quot;); Console.WriteLine($&quot;试试 0.1 + 0.2 == 0.3？结果是：&#123;(0.1 + 0.2 == 0.3)&#125; (因为 0.1 和 0.2 在二进制里是无限循环，产生了误差)&quot;); &#125;&#125; CSAPP 工程原则： 判断两个浮点数是否相等，永远、永远不要使用 ==。必须计算它们的差的绝对值是否小于一个极小值 epsilon（如 Math.Abs(x - y) &lt; 1e-6）。 把大数字和小数字相加时，要万分小心。如果有大量数字求和，应该先把所有小数字加起来，最后再去加那个极大的数字，这样能将精度丢失降到最低。 终极总结与执行入口 恭喜你！到这里，你已经完全通关了 CSAPP 第二章《信息的表示与处理》中最硬核、最底层的知识： 我们从 0 和 1 出发，学习了十六进制。 我们见识了内存里大端法和小端法的勾心斗角。 我们用“掩码和移位”的魔法在位级别翻江倒海。 我们理解了补码的“资产与债务”，揭开了正负溢出与回绕的真相。 最后，我们扒开了 IEEE 754 浮点数的皮囊，看透了规格化、舍入机制与结合律失效的陷阱。 这几篇笔记虽然只覆盖了一章的一半，但它们构筑了你作为“底层黑客”的地基。当你以后写出任何高级的 C# 代码时，你不再是只能看到一堆英文单词，你现在能够“透视”它们在 CPU 和内存里的真实模样。 浮点数部分完整运行代码： 123456789101112131415using System;class Program&#123; static void Main(string[] args) &#123; Console.WriteLine(&quot;====== CSAPP: 浮点数 (IEEE 754) 终极解密 ======
